<?php
require_once __DIR__.'/config.php';$id=valid_id($_GET['id']??0);$stmt=$pdo->prepare("SELECT r.*,s.name subject_name,c.name category_name,u.name uploader FROM resources r JOIN subjects s ON s.id=r.subject_id JOIN categories c ON c.id=r.category_id JOIN users u ON u.id=r.uploader_id WHERE r.id=? AND r.status='approved'");$stmt->execute([$id]);$r=$stmt->fetch();if(!$r){http_response_code(404);$pageTitle='Resource not found';require __DIR__.'/includes/header.php';echo '<div class="container page-content"><div class="empty-state"><h2>Resource not found</h2><p>This resource may be pending review or no longer available.</p><a class="btn btn-primary" href="resources.php">Back to resources</a></div></div>';require __DIR__.'/includes/footer.php';exit;}
$pageTitle=$r['title'];$errors=[];
if(is_post()){require_login();verify_csrf();$action=$_POST['action']??'';
if($action==='rate'){$rating=(int)($_POST['rating']??0);if($rating<1||$rating>5){set_flash('error','Choose a rating from 1 to 5.');}else{$pdo->prepare("INSERT INTO resource_ratings(resource_id,user_id,rating) VALUES(?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),created_at=CURRENT_TIMESTAMP")->execute([$id,current_user()['id'],$rating]);set_flash('success','Thanks for rating this resource.');}redirect('resource.php?id='.$id);}
if($action==='comment'){$body=posted_string('body',2000);if(mb_strlen($body)<3)set_flash('error','Your comment is too short.');else{$pdo->prepare("INSERT INTO resource_comments(resource_id,user_id,body,status) VALUES(?,?,?,'visible')")->execute([$id,current_user()['id'],$body]);set_flash('success','Your comment has been added.');}redirect('resource.php?id='.$id);}
}
$ratings=$pdo->prepare("SELECT COALESCE(AVG(rating),0) avg_rating,COUNT(*) total FROM resource_ratings WHERE resource_id=?");$ratings->execute([$id]);$ratingInfo=$ratings->fetch();
$comments=$pdo->prepare("SELECT rc.*,u.name FROM resource_comments rc JOIN users u ON u.id=rc.user_id WHERE rc.resource_id=? AND rc.status='visible' ORDER BY rc.created_at DESC");$comments->execute([$id]);$comments=$comments->fetchAll();
$related=$pdo->prepare("SELECT id,title,description FROM resources WHERE status='approved' AND subject_id=? AND id<>? ORDER BY created_at DESC LIMIT 3");$related->execute([$r['subject_id'],$id]);$related=$related->fetchAll();
require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><a href="resources.php">← Back to resources</a><div class="mt-2"><span class="eyebrow"><?= e($r['category_name']) ?> · <?= e($r['subject_name']) ?></span><h1><?= e($r['title']) ?></h1><p>Shared by <?= e($r['uploader']) ?> · <?= e(date('F j, Y',strtotime($r['created_at']))) ?></p></div></div></section>
<div class="page-content"><div class="container detail-layout"><div class="content-stack"><article class="panel"><h2>About this resource</h2><p class="detail-content"><?= e($r['description']) ?></p><div class="separator"></div><p><strong>File type:</strong> <?= e(strtoupper($r['file_type'])) ?></p><p><strong>Subject:</strong> <?= e($r['subject_name']) ?></p><a class="btn btn-primary" href="download.php?id=<?= $id ?>">↓ Download resource</a></article>
<section class="panel"><h2>Comments and feedback</h2><?php if(current_user()): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="comment"><div class="form-group"><label for="body">Add a comment</label><textarea id="body" name="body" maxlength="2000" required placeholder="Was this resource helpful?"></textarea></div><button class="btn btn-primary btn-small">Post comment</button></form><?php else: ?><p><a href="login.php">Log in</a> to comment or rate this resource.</p><?php endif; ?><div class="separator"></div><?php if($comments): foreach($comments as $c): ?><div class="mb-2"><strong><?= e($c['name']) ?></strong><span class="small-muted"> · <?= e(date('M j, Y',strtotime($c['created_at']))) ?></span><p><?= e($c['body']) ?></p></div><?php endforeach; else: ?><p>No comments yet. Start the conversation.</p><?php endif; ?></section></div>
<aside class="content-stack"><section class="panel"><h3>Community rating</h3><div class="rating-row"><strong><?= number_format((float)$ratingInfo['avg_rating'],1) ?>/5</strong><span>★</span></div><p><?= (int)$ratingInfo['total'] ?> ratings</p><?php if(current_user()): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="rate"><div class="form-group"><label for="rating">Your rating</label><select id="rating" name="rating" required><option value="">Choose a rating</option><?php for($i=5;$i>=1;$i--): ?><option value="<?= $i ?>"><?= $i ?> — <?= ['1'=>'Not helpful','2'=>'Fair','3'=>'Useful','4'=>'Very useful','5'=>'Excellent'][(string)$i] ?></option><?php endfor; ?></select></div><button class="btn btn-outline btn-block">Submit rating</button></form><?php endif; ?></section>
<section class="panel"><h3>Related resources</h3><?php if($related): foreach($related as $rr): ?><p><a href="resource.php?id=<?= (int)$rr['id'] ?>"><strong><?= e($rr['title']) ?></strong></a><br><span class="small-muted"><?= e(excerpt($rr['description'],80)) ?></span></p><?php endforeach; else: ?><p>No related resources yet.</p><?php endif; ?></section></aside></div></div>
<?php require __DIR__.'/includes/footer.php';?>
